  P.cloud = (x, y, s, c, sh) => { const B = [[0, 0, 40], [38, -18, 46], [82, -4, 38], [118, 8, 30], [-34, 10, 28]]; const bl = (dy, dr) => B.map(([bx, by, r]) => circ(x + bx * s, y + (by + dy) * s, r * s + dr)).join(''); const curl = (cx, cy, r) => `M${f(cx)} ${f(cy)}a${f(r)} ${f(r)} 0 1 1 ${f(r * 1.2)} ${f(r * .6)}a${f(r * .5)} ${f(r * .5)} 0 1 1 ${f(-r * .6)} ${f(-r * .5)}`; return `<g class="cloud-g"><path d="${bl(4, 4)}" fill="${K}"/><path d="${bl(10, 0)}" fill="${sh}"/><path d="${bl(10, 0)}" fill="url(#@d)" opacity=".25"/><path d="${bl(0, 0)}" fill="${c}"/><path d="${curl(x + 20 * s, y - 20 * s, 12 * s)}${curl(x + 76 * s, y - 14 * s, 10 * s)}${curl(x - 26 * s, y + 4 * s, 7 * s)}" stroke="${K}" stroke-width="${f(Math.max(1.4, 2.4 * s))}" fill="none" opacity=".55"/></g>`; };
