  /* ================= shared layer pieces ================= */
  function ridgeD(r, base, amp, steps, jag) { const ys = []; for (let i = 0; i <= steps; i++) ys.push(base - r() * amp); ys[steps] = ys[0]; let d = `M0 ${H}`; for (let i = 0; i <= steps; i++) { d += `L${f(i / steps * W)} ${f(ys[i])}`; if (jag && i < steps) d += `L${f((i + .5) / steps * W)} ${f(ys[i] - amp * .4 * r())}`; } return d + `L${W} ${H}Z`; }
  function hillsD(r, base, amp, n) { const ys = []; for (let i = 0; i <= n; i++) ys.push(base - r() * amp); ys[n] = ys[0]; let d = `M0 ${H}L0 ${f(ys[0])}`; for (let i = 0; i < n; i++) { const x0 = i / n * W, x1 = (i + 1) / n * W; d += `Q${f((x0 + x1) / 2)} ${f(Math.min(ys[i], ys[i + 1]) - amp * .5)} ${f(x1)} ${f(ys[i + 1])}`; } return d + `L${W} ${H}Z`; }
