  /** dune/furrow strokes on the ground, drawn toward a vanishing point (the exaggerated perspective) */
  const furrows = (col, r, y0 = 520, n = 14, op = .55) => { let d = ''; for (let i = 0; i < n; i++) { const x = r() * W, y = y0 + r() * (H - y0 - 10), w = 60 + r() * 140; d += `M${f(x)} ${f(y)}q${f(w / 2)} -6 ${f(w)} 0`; } return `<path d="${d}" stroke="${col}" stroke-width="3" fill="none" opacity="${op}"/>`; };
  const tufts = (col, r, y0, y1, n) => { let d = ''; for (let i = 0; i < n; i++) { const x = r() * W, y = y0 + r() * (y1 - y0), h = 8 + r() * 14; d += `M${f(x)} ${f(y)}q-3 ${f(-h * .6)} -6 ${f(-h)}M${f(x)} ${f(y)}q1 ${f(-h * .8)} 2 ${f(-h * 1.1)}M${f(x)} ${f(y)}q3 ${f(-h * .6)} 7 ${f(-h * .85)}`; } return `<path d="${d}" stroke="${K}" stroke-width="4" fill="none"/><path d="${d}" stroke="${col}" stroke-width="2" fill="none"/>`; };
