    X.mid += `<path d="${rails}" stroke="#b8b8c8" stroke-width="3"/>` + T(840, 322, 1, P.lantern()) + `<circle cx="${vx}" cy="${vy + 10}" r="8" fill="#f2c14e" fill-opacity=".8" class="sx-glow"/>`;
